  // src/systems/photos.js
  function grain(c, x, y, w, h2, a = 0.08) {
    c.save();
    for (let i = 0; i < w * h2 / 40; i++) {
      c.fillStyle = Math.random() < 0.5 ? `rgba(255,255,255,${a})` : `rgba(0,0,0,${a})`;
      c.fillRect(x + Math.random() * w, y + Math.random() * h2, 1.2, 1.2);
    }
    c.restore();
  }
  function person(c, x, y, s, color = "#0a0a0c", hair = false) {
    c.fillStyle = color;
    c.beginPath();
    c.ellipse(x, y - s * 0.78, s * 0.12, s * 0.14, 0, 0, Math.PI * 2);
    c.fill();
    if (hair) {
      c.beginPath();
      c.ellipse(x, y - s * 0.72, s * 0.15, s * 0.2, 0, Math.PI, Math.PI * 2);
      c.fill();
      c.fillRect(x - s * 0.15, y - s * 0.74, s * 0.06, s * 0.25);
      c.fillRect(x + s * 0.09, y - s * 0.74, s * 0.06, s * 0.25);
    }
    c.beginPath();
    c.moveTo(x - s * 0.22, y);
    c.quadraticCurveTo(x - s * 0.24, y - s * 0.6, x, y - s * 0.62);
    c.quadraticCurveTo(x + s * 0.24, y - s * 0.6, x + s * 0.22, y);
    c.fill();
  }
