      setTimeout(() => g.audio.play("casing", { vol: 0.35, pos: new Vector3(p.pos.x + 0.4, p.pos.y + 0.05, p.pos.z) }), 380);
      g.noise.emit(p.pos.x, p.pos.z, 28, "gunshot");
