            c.sound("hiss", [x, 1.3, z + 0.3], { vol: 0.9 });
            g.fx.puff(x, 1.2, z + 0.5, { rise: true, n: 80, w: 0.8, d: 0.8, life: 2.6, size: 0.45 });
