          await c.wait(0.8);
          c.loop("horn", "klaxon", [80.5, 3.8, 46.5], { vol: 0.9, bus: "sfx", ref: 6, rolloff: 0.6 });
          c.noise(80, 44, 40, "alarm");
          c.noise(70, 5, 40, "alarm");
          const d = c.door("shutter");
          d.setLocked(false);
          d.open(null, { force: true });
          d.speed = 0.13;
          g.level.lights.byId("shutterLamp").color.setHex(16756768);
          await c.lines([{ s: "ilyas", t: "Das Tor geht hoch. Lauft! Runter auf minus zwei \u2013 S\xFCdseite!", v: "i3_j" }]);
          for (const n of g.npcs) n.follow();
          c.objective("Lauf zum Rolltor auf Ebene \u22122 (S\xFCd)!");
          const t = g.difficulty.chaseTime;
          await c.wait(1.5 * t);
          const spawn = (x, z, o) => {
            const s = c.spawn({ x, z, type: "hunter", ...o });
            s.forceChase();
            return s;
          };
          spawn(93.5, 3.5, { outfit: "civilian" });
          spawn(94.5, 5.5, { outfit: "soldier" });
          await c.wait(1.2 * t);
          spawn(92.5, 6.4, { outfit: "civilian2" });
          spawn(95.6, 4.2, { outfit: "suit" });
          c.wake("z2b");
          c.wake("z2c");
          await c.wait(2 * t);
          spawn(94, 2.8, { outfit: "civilian" });
          spawn(96, 6.5, { outfit: "security" });
