      L.zombie(45.6, 11.4, { id: "zd_1", type: "sleeper", pose: "lying", yaw: 1.2, outfit: "civilian", wake: 3.2 });
      L.zombie(44.5, 23.6, { id: "zp_st", type: "stalker", stalker: true, yaw: 0.3, outfit: "civilian" });
